export default function App(){
  const [tab,      setTab]      = useState("register");
  const [records,  setRecords]  = useState([]);
  const [loading,  setLoading]  = useState(true);
  const [done,     setDone]     = useState(null);
  const [preview,  setPreview]  = useState(null);
  const [payMethod,setPayMethod]= useState("");
  const [err,      setErr]      = useState({});
  const [saving,   setSaving]   = useState(false);

  // 管理者（Google 登入）
  const [user,      setUser]     = useState(null);
  const [isAdmin,   setIsAdmin]  = useState(false);
  const [authLoading,setAuthLoad]= useState(true);
  const [adminSrch, setAdminSrch]= useState("");
  const [dateFrom,  setDateFrom] = useState("");
  const [dateTo,    setDateTo]   = useState("");
  const [delConfirm,setDelConf]  = useState(null);

  // 查詢驗證
  const [qAuth,  setQAuth]  = useState(false);
  const [qInput, setQInput] = useState({name:"",phone:""});
  const [qErr,   setQErr]   = useState("");
  const [srch,   setSrch]   = useState("");

  // 進香報名
  const [pilRecords,   setPilRecords]   = useState([]);
  const [pilSettings,  setPilSettings]  = useState({enabled:false, title:"114年 進香報名", date:""});
  const [pilForm,      setPilForm]      = useState({name:"",phone:"",idNo:"",birthday:"",address:"",vegetarian:"葷食",note:""});
  const [pilErr,       setPilErr]       = useState({});
  const [pilDone,      setPilDone]      = useState(null);
  const [pilSaving,    setPilSaving]    = useState(false);
  const [pilAdminSrch, setPilAdminSrch] = useState("");
  const [pilDelConf,   setPilDelConf]   = useState(null);

  // Firebase Auth
  useEffect(()=>{
    // 處理 redirect 登入結果
    getRedirectResult(auth).then(result=>{
      if(result?.user){
        if(!ADMIN_EMAILS.includes(result.user.email)){
          signOut(auth);
          alert("此 Google 帳號沒有管理權限");
        }
      }
    }).catch(e=>{ if(e.code!=="auth/no-current-user") console.error(e); });

    const unsub = onAuthStateChanged(auth, u=>{
      setUser(u);
      setIsAdmin(u ? ADMIN_EMAILS.includes(u.email) : false);
      setAuthLoad(false);
    });
    return unsub;
  },[]);

  // 讀取 Firestore 資料
  const fetchRecords = useCallback(async()=>{
    setLoading(true);
    try {
      const q = query(collection(db,"registrations"), orderBy("createdAt","desc"));
      const snap = await getDocs(q);
      setRecords(snap.docs.map(d=>({id:d.id,...d.data()})));
    } catch(e){ console.error(e); }
    setLoading(false);
  },[]);

  useEffect(()=>{ fetchRecords(); },[fetchRecords]);

  const fetchPilRecords = useCallback(async()=>{
    try {
      const q = query(collection(db,"pilRecords"), orderBy("createdAt","desc"));
      const snap = await getDocs(q);
      setPilRecords(snap.docs.map(d=>({id:d.id,...d.data()})));
    } catch(e){ console.error(e); }
  },[]);

  const fetchPilSettings = useCallback(async()=>{
    try {
      const snap = await getDocs(collection(db,"pilSettings"));
      if(!snap.empty){ setPilSettings(snap.docs[0].data()); }
    } catch(e){ console.error(e); }
  },[]);

  useEffect(()=>{ fetchPilRecords(); fetchPilSettings(); },[fetchPilRecords, fetchPilSettings]);

  const blankForm = ()=>({
    name:"", gender:"男", birthYear:2000,
    lunarMonth:"1月", lunarDay:"1日",
    phone:"", address:"",
    cats:[], lights:[], pudos:[], pudoNotes:{},
    treasurySeason:"", sponsorAmount:"", note:"",
  });
  const [form, setForm] = useState(blankForm);
  const set = (k,v) => setForm(f=>({...f,[k]:v}));
  const clrE = (...ks) => setErr(e=>{ const n={...e}; ks.forEach(k=>delete n[k]); return n; });

  const total =
    (form.lights||[]).reduce((s,id)=>s+(LIGHT_ITEMS.find(x=>x.id===id)?.price||0),0)+
    (form.pudos ||[]).reduce((s,id)=>s+(PUDO_ITEMS .find(x=>x.id===id)?.price||0),0)+
    (form.cats?.includes("treasury")?1500:0)+
    (form.cats?.includes("restore") ?1500:0)+
    (form.cats?.includes("sponsor") ?(+form.sponsorAmount||0):0);

  const toggleCat = id => {
    const next = form.cats.includes(id)?form.cats.filter(c=>c!==id):[...form.cats,id];
    const nf = {...form,cats:next};
    if(!next.includes("light"))    nf.lights=[];
    if(!next.includes("pudo"))    {nf.pudos=[];nf.pudoNotes={};}
    if(!next.includes("treasury")) nf.treasurySeason="";
    if(!next.includes("sponsor"))  nf.sponsorAmount="";
    setForm(nf); clrE("cats","lights","pudos","treasurySeason","sponsorAmount");
  };
  const toggleSub = (arr,id,key) => {
    set(key,arr.includes(id)?arr.filter(x=>x!==id):[...arr,id]);
    clrE(key);
  };

  const validate = () => {
    const e={};
    if(!form.name.trim())    e.name    = "請填寫姓名";
    if(!form.phone.trim())   e.phone   = "請填寫聯絡電話";
    if(!form.address.trim()) e.address = "請填寫地址";
    if(form.cats.length===0) e.cats    = "請選擇至少一個項目類別";
    if(form.cats.includes("light") && form.lights.length===0)  e.lights = "請選擇燈種";
    if(form.cats.includes("pudo")  && form.pudos.length===0)   e.pudos  = "請選擇普渡項目";
    if(form.pudos.includes("ancestor")&&!form.pudoNotes?.ancestor?.trim()) e.noteAncestor="請填寫祖先姓名";
    if(form.pudos.includes("baby")    &&!form.pudoNotes?.baby?.trim())     e.noteBaby    ="請填寫嬰靈資訊";
    if(form.cats.includes("treasury") &&!form.treasurySeason) e.treasurySeason="請選擇春季或秋季";
    if(form.cats.includes("sponsor")&&(!form.sponsorAmount||+form.sponsorAmount<=0)) e.sponsorAmount="請填寫善款金額";
    setErr(e);
    return Object.keys(e).length===0;
  };

  const submit = () => {
    if(!validate()) return;
    setPreview({...form,total});
    setPayMethod("");
    setTab("confirm");
  };

  const confirmSubmit = async method => {
    setSaving(true);
    try {
      const now = new Date();
      const serialNo = `SXG${now.getTime().toString().slice(-6)}`;
      const rec = {
        serialNo,
        registeredAt: now.toLocaleString("zh-TW"),
        createdAt: now.toISOString(),
        ...preview,
        payMethod: method,
        payStatus: "pending",
      };
      const docRef = await addDoc(collection(db,"registrations"), rec);
      const saved = {id:docRef.id, ...rec};
      setRecords(r=>[saved,...r]);
      setDone(saved);
      setPreview(null); setPayMethod("");
      setForm(blankForm()); setErr({});
      setTab("done");
    } catch(e){
      alert("儲存失敗，請確認網路連線："+e.message);
    }
    setSaving(false);
  };

  const updatePayStatus = async (recordId, status) => {
    try {
      await updateDoc(doc(db,"registrations",recordId),{payStatus:status});
      setRecords(r=>r.map(x=>x.id===recordId?{...x,payStatus:status}:x));
    } catch(e){ alert("更新失敗："+e.message); }
  };

  const deleteRecord = async id => {
    try {
      await deleteDoc(doc(db,"registrations",id));
      setRecords(r=>r.filter(x=>x.id!==id));
      setDelConf(null);
    } catch(e){ alert("刪除失敗："+e.message); }
  };

  const doQueryAuth = () => {
    if(!qInput.name.trim()||!qInput.phone.trim()){ setQErr("請填寫姓名及電話"); return; }
    const ok = records.some(r=>r.name===qInput.name.trim()&&r.phone===qInput.phone.trim());
    if(ok){ setQAuth(true); setQErr(""); }
    else setQErr("查無符合資料，請確認姓名及電話是否正確");
  };

  const loginAdmin = async () => {
    try {
      // iOS Safari 不支援 popup，改用 redirect
      await signInWithRedirect(auth, provider);
    } catch(e){ alert("登入失敗："+e.message); }
  };

  const adminFiltered = records.filter(r=>{
    const textMatch = !adminSrch||r.name?.includes(adminSrch)||r.phone?.includes(adminSrch)||r.serialNo?.includes(adminSrch);
    let dateMatch = true;
    if(dateFrom||dateTo){
      const parts = r.registeredAt?.split(" ")[0]?.split("/");
      if(parts&&parts.length===3){
        const rDate = new Date(+parts[0],+parts[1]-1,+parts[2]);
        if(dateFrom){ const f=new Date(dateFrom); if(rDate<f) dateMatch=false; }
        if(dateTo)  { const t=new Date(dateTo);   if(rDate>t) dateMatch=false; }
      }
    }
    return textMatch&&dateMatch;
  });

  const setPil = (k,v) => setPilForm(f=>({...f,[k]:v}));
  const clrPilE = (...ks) => setPilErr(e=>{ const n={...e}; ks.forEach(k=>delete n[k]); return n; });

  const validatePil = () => {
    const e={};
    if(!pilForm.name.trim())    e.name    = "請填寫姓名";
    if(!pilForm.phone.trim())   e.phone   = "請填寫電話";
    if(!pilForm.idNo.trim())    e.idNo    = "請填寫身分證字號";
    if(!pilForm.birthday.trim())e.birthday= "請填寫生日";
    if(!pilForm.address.trim()) e.address = "請填寫地址";
    setPilErr(e);
    return Object.keys(e).length===0;
  };

  const submitPil = async () => {
    if(!validatePil()) return;
    setPilSaving(true);
    try {
      const now = new Date();
      const serialNo = `XJ${now.getTime().toString().slice(-6)}`;
      const rec = {
        serialNo, registeredAt: now.toLocaleString("zh-TW"),
        createdAt: now.toISOString(),
        ...pilForm, amount:"", payStatus:"pending",
      };
      const docRef = await addDoc(collection(db,"pilRecords"), rec);
      const saved = {id:docRef.id, ...rec};
      setPilRecords(r=>[saved,...r]);
      setPilDone(saved);
      setPilForm({name:"",phone:"",idNo:"",birthday:"",address:"",vegetarian:"葷食",note:""});
      setPilErr({});
    } catch(e){ alert("儲存失敗："+e.message); }
    setPilSaving(false);
  };

  const updatePilStatus = async (id, status) => {
    try {
      await updateDoc(doc(db,"pilRecords",id),{payStatus:status});
      setPilRecords(r=>r.map(x=>x.id===id?{...x,payStatus:status}:x));
    } catch(e){ alert("更新失敗："+e.message); }
  };

  const updatePilAmount = async (id, amount) => {
    try {
      await updateDoc(doc(db,"pilRecords",id),{amount});
      setPilRecords(r=>r.map(x=>x.id===id?{...x,amount}:x));
    } catch(e){ alert("更新失敗："+e.message); }
  };

  const deletePilRecord = async id => {
    try {
      await deleteDoc(doc(db,"pilRecords",id));
      setPilRecords(r=>r.filter(x=>x.id!==id));
      setPilDelConf(null);
    } catch(e){ alert("刪除失敗："+e.message); }
  };

  const savePilSettings = async (newSettings) => {
    try {
      const snap = await getDocs(collection(db,"pilSettings"));
      if(snap.empty){
        await addDoc(collection(db,"pilSettings"), newSettings);
      } else {
        await updateDoc(doc(db,"pilSettings",snap.docs[0].id), newSettings);
      }
      setPilSettings(newSettings);
    } catch(e){ alert("設定儲存失敗："+e.message); }
  };

  const exportPilCSV = (records) => {
    const H = ["登記編號","登記日期","姓名","電話","身分證","生日","地址","葷素","金額","付款狀態","備註"];
    const rows = records.map(r=>[
      r.serialNo, r.registeredAt, r.name, r.phone, r.idNo, r.birthday,
      r.address, r.vegetarian, r.amount||"", 
      PAY_STATUS.find(x=>x.id===(r.payStatus||"pending"))?.label||"待付款", r.note||"",
    ]);
    const esc = v => `"${String(v).replace(/"/g,'""')}"`;
    const csv = "\uFEFF"+[H,...rows].map(r=>r.map(esc).join(",")).join("\r\n");
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8;"}));
    a.download = `受玄宮進香報名_${new Date().toLocaleDateString("zh-TW").replace(/\//g,"")}.csv`;
    a.click();
  };

  const TABS = [
    {id:"register",label:"登記"},
    ...(pilSettings.enabled ? [{id:"pilgrim",label:"進香報名"}] : []),
    {id:"records",label:"查詢"},
    {id:"admin",label:"管理"},
  ];

  if(authLoading) return <div style={{display:"flex",alignItems:"center",justifyContent:"center",height:"100vh",background:C.bg,color:C.sub,fontFamily:"inherit"}}>載入中...</div>;

  return (
    <div style={{minHeight:"100vh",background:C.bg,fontFamily:"'Noto Serif TC',Georgia,serif",color:C.text}}>

      {/* Header */}
      <div style={{borderBottom:`3px solid ${C.gold}`,boxShadow:"0 2px 12px #0000001a",background:"#1a0800"}}>
        <div style={{width:"100%",lineHeight:0}}>
          <img src={HEADER_IMG} alt="八里無極受玄宮" style={{width:"100%",display:"block",height:"auto",maxHeight:"clamp(80px,15vw,180px)",objectFit:"cover",objectPosition:"center center"}}/>
        </div>
        <div style={{background:"linear-gradient(135deg,#9b3a3a,#7a2a2a)",textAlign:"center",padding:"6px 16px 0"}}>
          <div style={{fontSize:12,color:"#f0d090",letterSpacing:3,opacity:.9}}>活動登記系統</div>
        </div>
        <div style={{background:"linear-gradient(135deg,#9b3a3a,#7a2a2a)",display:"flex",justifyContent:"center",gap:2,padding:"4px 16px 0"}}>
          {TABS.map(t=>(
            <button key={t.id} onClick={()=>{
              if(t.id==="admin"){
                if(!user) loginAdmin();
                else if(isAdmin) setTab("admin");
                else alert("此帳號沒有管理權限");
              } else setTab(t.id);
            }} style={{
              padding:"8px 22px",border:"none",cursor:"pointer",fontFamily:"inherit",
              fontSize:13,letterSpacing:2,borderRadius:"8px 8px 0 0",
              background:tab===t.id?"#faf6f0":"transparent",
              color:tab===t.id?C.red:"#f5e6c8",fontWeight:tab===t.id?700:400,
            }}>{t.label}{t.id==="admin"&&isAdmin?" ✓":""}</button>
          ))}
        </div>
      </div>

      {/* LINE 列 */}
      <div style={{background:"#06C755",textAlign:"center",padding:"8px 16px",display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>
        {LINE_SVG_SM}
        <a href={LINE_URL} target="_blank" rel="noreferrer" style={{color:"#fff",fontSize:13,fontWeight:700,textDecoration:"none",letterSpacing:1}}>
          加入官方 LINE 獲得最新消息
        </a>
      </div>

      {/* 刪除確認 Modal */}
      {delConfirm&&(
        <div style={{position:"fixed",inset:0,background:"#0006",zIndex:999,display:"flex",alignItems:"center",justifyContent:"center"}}>
          <div style={{background:"#fff",borderRadius:16,padding:"24px",width:280,boxShadow:"0 8px 32px #0003",textAlign:"center"}}>
            <div style={{fontSize:22,marginBottom:10}}>⚠️</div>
            <div style={{fontWeight:700,color:C.text,marginBottom:6}}>確認刪除此筆資料？</div>
            <div style={{fontSize:13,color:C.sub,marginBottom:18}}>{delConfirm.name}・{delConfirm.serialNo}</div>
            <div style={{display:"flex",gap:10}}>
              <button onClick={()=>setDelConf(null)} style={{flex:1,padding:"9px 0",background:C.bg,border:`1px solid ${C.border}`,borderRadius:8,cursor:"pointer",fontFamily:"inherit",fontSize:13,color:C.sub}}>取消</button>
              <button onClick={()=>deleteRecord(delConfirm.id)} style={{flex:1,padding:"9px 0",background:C.red,border:"none",borderRadius:8,cursor:"pointer",fontFamily:"inherit",fontSize:13,color:"#fff",fontWeight:700}}>刪除</button>
            </div>
          </div>
        </div>
      )}

      <div style={{maxWidth:600,margin:"0 auto",padding:"18px 14px 80px"}}>

        {/* ═══ 登記 ═══ */}
        {tab==="register"&&(
        <div>
          <Section title="信眾基本資料" icon="📋">
            <div style={{marginBottom:12}}>
              <Lbl t="姓名 *"/>
              <input value={form.name} onChange={e=>{set("name",e.target.value);clrE("name");}} placeholder="請輸入姓名" style={inp}/>
              <Err c={err.name}/>
            </div>
            <div style={{marginBottom:12}}>
              <Lbl t="性別"/>
              <div style={{display:"flex",gap:20}}>
                {["男","女"].map(g=>(
                  <label key={g} style={{display:"flex",alignItems:"center",gap:6,cursor:"pointer",fontSize:14}}>
                    <input type="radio" checked={form.gender===g} onChange={()=>set("gender",g)} style={{accentColor:C.red}}/>{g}
                  </label>
                ))}
              </div>
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:12}}>
              <div>
                <Lbl t="出生年（民國）"/>
                <select value={form.birthYear} onChange={e=>set("birthYear",+e.target.value)} style={inp}>
                  {YEARS.map(y=><option key={y} value={y}>民國{toROC(y)}年（{zodiac(y)}）</option>)}
                </select>
              </div>
              <div>
                <Lbl t="農曆生日"/>
                <div style={{display:"flex",gap:6}}>
                  <select value={form.lunarMonth} onChange={e=>set("lunarMonth",e.target.value)} style={{...inp,padding:"9px 6px"}}>
                    {L_MON.map(m=><option key={m}>{m}</option>)}
                  </select>
                  <select value={form.lunarDay} onChange={e=>set("lunarDay",e.target.value)} style={{...inp,padding:"9px 6px"}}>
                    {L_DAY.map(d=><option key={d}>{d}</option>)}
                  </select>
                </div>
              </div>
            </div>
            <div style={{marginBottom:12}}>
              <Lbl t="聯絡電話 *"/>
              <input value={form.phone} onChange={e=>{set("phone",e.target.value);clrE("phone");}} placeholder="0912-345-678" style={inp}/>
              <Err c={err.phone}/>
            </div>
            <div style={{marginBottom:12}}>
              <Lbl t="地址 *"/>
              <input value={form.address} onChange={e=>{set("address",e.target.value);clrE("address");}} placeholder="請輸入地址" style={inp}/>
              <Err c={err.address}/>
            </div>
          </Section>

          <Section title="登記項目（可複選）" icon="📌">
            <Err c={err.cats}/>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginTop:4}}>
              {CATS.map(cat=>{
                const sel=form.cats.includes(cat.id);
                return (
                  <div key={cat.id} onClick={()=>toggleCat(cat.id)} style={{textAlign:"center",padding:"16px 8px",cursor:"pointer",borderRadius:10,border:`2px solid ${sel?C.red:C.border}`,background:sel?C.redL:C.bg,transition:"all .15s"}}>
                    <div style={{fontSize:24,marginBottom:5}}>{cat.icon}</div>
                    <div style={{fontWeight:700,fontSize:14,color:sel?C.red:C.sub,letterSpacing:1}}>{cat.label}</div>
                    {sel&&<div style={{fontSize:11,color:C.gold,marginTop:4}}>✓ 已選</div>}
                  </div>
                );
              })}
            </div>
          </Section>

          {form.cats.includes("light")&&(
            <Section title="燈種選擇（每盞 $600）" icon="🏮">
              <Err c={err.lights}/>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:10,marginTop:4}}>
                {LIGHT_ITEMS.map(lt=>{
                  const sel=form.lights.includes(lt.id);
                  return(
                    <div key={lt.id} onClick={()=>toggleSub(form.lights,lt.id,"lights")} style={{textAlign:"center",padding:"14px 8px",cursor:"pointer",borderRadius:10,border:`2px solid ${sel?C.gold:C.border}`,background:sel?C.goldL:C.bg,transition:"all .15s"}}>
                      <div style={{fontSize:20,marginBottom:4}}>🏮</div>
                      <div style={{fontWeight:700,fontSize:13,color:sel?C.gold:C.sub}}>{lt.label}</div>
                      <div style={{fontSize:12,color:C.muted,marginTop:3}}>$600</div>
                    </div>
                  );
                })}
              </div>
            </Section>
          )}

          {form.cats.includes("pudo")&&(
            <Section title="普渡項目（每項 $1,500）" icon="🪔">
              <Err c={err.pudos}/>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginTop:4}}>
                {PUDO_ITEMS.map(p=>{
                  const sel=form.pudos.includes(p.id);
                  return(
                    <div key={p.id} style={{borderRadius:10,border:`2px solid ${sel?"#9b6a3a":C.border}`,background:sel?"#fdf3ea":C.bg,transition:"all .15s",overflow:"hidden"}}>
                      <div onClick={()=>toggleSub(form.pudos,p.id,"pudos")} style={{padding:"12px 14px",cursor:"pointer",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                        <span style={{fontWeight:700,fontSize:13,color:sel?"#9b6a3a":C.sub}}>{p.label}</span>
                        <span style={{fontSize:12,color:C.muted}}>$1,500</span>
                      </div>
                      {sel&&p.hasNote&&(
                        <div style={{padding:"0 12px 12px"}}>
                          <div style={{fontSize:11,marginBottom:4,color:(p.id==="ancestor"&&err.noteAncestor)||(p.id==="baby"&&err.noteBaby)?C.red:C.muted}}>
                            {p.id==="ancestor"?"填寫祖先姓名 *":"填寫嬰靈資訊 *"}
                          </div>
                          <textarea value={form.pudoNotes[p.id]||""} rows={3}
                            onChange={e=>{setForm(f=>({...f,pudoNotes:{...f.pudoNotes,[p.id]:e.target.value}}));clrE(p.id==="ancestor"?"noteAncestor":"noteBaby");}}
                            placeholder={p.id==="ancestor"?"例：○○○ 歷代祖先...":"例：民國○年○月○日..."}
                            onClick={e=>e.stopPropagation()}
                            style={{...inp,resize:"vertical",fontSize:12,lineHeight:1.6,borderColor:(p.id==="ancestor"&&err.noteAncestor)||(p.id==="baby"&&err.noteBaby)?C.red:C.border}}/>
                          {p.id==="ancestor"&&<Err c={err.noteAncestor}/>}
                          {p.id==="baby"    &&<Err c={err.noteBaby}/>}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </Section>
          )}

          {form.cats.includes("treasury")&&(
            <Section title="補財庫（$1,500）" icon="💰">
              <div style={{fontSize:13,color:C.sub,marginBottom:10}}>請選擇季別 *</div>
              <div style={{display:"flex",gap:10}}>
                {["春季","秋季"].map(s=>(
                  <div key={s} onClick={()=>{set("treasurySeason",s);clrE("treasurySeason");}} style={{flex:1,textAlign:"center",padding:"12px 0",cursor:"pointer",borderRadius:8,border:`2px solid ${form.treasurySeason===s?"#9b6a3a":C.border}`,background:form.treasurySeason===s?"#fdf3ea":"#fff",color:form.treasurySeason===s?"#9b6a3a":C.sub,fontWeight:form.treasurySeason===s?700:400,fontSize:15,transition:"all .15s"}}>
                    {s==="春季"?"🌸":"🍂"} {s}
                  </div>
                ))}
              </div>
              <Err c={err.treasurySeason}/>
            </Section>
          )}

          {form.cats.includes("restore")&&(
            <Section title="還庫藏（$1,500）" icon="✨">
              <div style={{borderRadius:8,background:"#f5f0fa",border:`1px solid ${C.border}`,padding:"12px 14px",fontSize:13,color:C.sub}}>
                已選擇還庫藏，費用 NT$1,500。如有特殊說明請填寫於備註。
              </div>
            </Section>
          )}

          {form.cats.includes("sponsor")&&(
            <Section title="善款" icon="🙏">
              <div style={{marginBottom:10,fontSize:13,color:C.sub}}>感謝您的慷慨捐助，請填寫善款金額</div>
              <Lbl t="善款金額（元）*"/>
              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:4}}>
                <span style={{fontSize:16,color:C.sub}}>NT$</span>
                <input type="number" min="1" value={form.sponsorAmount}
                  onChange={e=>{set("sponsorAmount",e.target.value);clrE("sponsorAmount");}}
                  placeholder="請輸入金額" style={{...inp,flex:1,fontSize:16}}/>
              </div>
              <Err c={err.sponsorAmount}/>
              <div style={{display:"flex",gap:8,marginTop:10,flexWrap:"wrap"}}>
                {[500,1000,3000,5000,10000].map(amt=>(
                  <div key={amt} onClick={()=>{set("sponsorAmount",String(amt));clrE("sponsorAmount");}} style={{padding:"6px 14px",borderRadius:20,cursor:"pointer",fontSize:13,border:`1px solid ${+form.sponsorAmount===amt?"#9b6a3a":C.border}`,background:+form.sponsorAmount===amt?"#fdf3ea":C.bg,color:+form.sponsorAmount===amt?"#9b6a3a":C.sub,fontWeight:+form.sponsorAmount===amt?700:400}}>
                    ${amt.toLocaleString()}
                  </div>
                ))}
              </div>
            </Section>
          )}

          <Section title="備註" icon="📝">
            <textarea value={form.note} onChange={e=>set("note",e.target.value)} placeholder="特殊祈求事項（選填）" rows={3} style={{...inp,resize:"vertical",lineHeight:1.6}}/>
          </Section>

          <div style={{background:"#fff",border:`1px solid ${C.border}`,borderRadius:12,padding:"14px 18px",marginBottom:14,boxShadow:"0 1px 4px #0000000a"}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
              <div style={{color:C.sub,fontSize:13}}>
                {[form.lights.length>0&&`點燈×${form.lights.length}`,form.pudos.length>0&&`普渡×${form.pudos.length}`,form.cats.includes("treasury")&&`補財庫${form.treasurySeason?`(${form.treasurySeason})`:""}`,form.cats.includes("restore")&&"還庫藏",form.cats.includes("sponsor")&&`善款 NT${(+form.sponsorAmount||0).toLocaleString()}`].filter(Boolean).join("　")||"尚未選擇項目"}
              </div>
              <div style={{fontSize:20,fontWeight:900,color:C.red}}>NT$ {total.toLocaleString()}</div>
            </div>
          </div>
          <button onClick={submit} style={{width:"100%",padding:"15px 0",background:`linear-gradient(135deg,${C.red},#7a2a2a)`,border:`2px solid ${C.gold}`,borderRadius:12,color:"#fff",fontSize:16,fontWeight:700,letterSpacing:4,cursor:"pointer",fontFamily:"inherit",boxShadow:"0 3px 12px #9b3a3a30"}}>
            🏮 下一步：確認資料
          </button>
        </div>
        )}

        {/* ═══ 確認頁 ═══ */}
        {tab==="confirm"&&preview&&(
        <div>
          <div style={{textAlign:"center",marginBottom:20}}>
            <div style={{fontSize:36,marginBottom:6}}>📋</div>
            <div style={{fontSize:19,fontWeight:700,color:C.red,letterSpacing:2,marginBottom:4}}>請確認登記資料</div>
            <div style={{fontSize:13,color:C.sub}}>確認無誤後，請選擇付款方式</div>
          </div>
          <div style={{background:"#fff",border:`1px solid ${C.border}`,borderRadius:14,padding:"18px",marginBottom:16,boxShadow:"0 1px 6px #0000000d"}}>
            <div style={{color:C.red,fontWeight:700,fontSize:13,letterSpacing:3,textAlign:"center",marginBottom:12,paddingBottom:10,borderBottom:`1px solid ${C.border}`}}>八里無極受玄宮　登記資料確認</div>
            <InfoRow label="信眾姓名" value={`${preview.name}（${preview.gender}）`}/>
            <InfoRow label="出生年次" value={`民國${toROC(preview.birthYear)}年（${zodiac(preview.birthYear)}）`}/>
            <InfoRow label="農曆生日" value={`${preview.lunarMonth}${preview.lunarDay}`}/>
            <InfoRow label="聯絡電話" value={preview.phone}/>
            <InfoRow label="地址"     value={preview.address}/>
            {preview.lights?.length>0&&<InfoRow label="點燈項目" value={preview.lights.map(id=>LIGHT_ITEMS.find(x=>x.id===id)?.label).join("、")}/>}
            {preview.pudos?.length>0&&<>
              <InfoRow label="普渡項目" value={preview.pudos.map(id=>PUDO_ITEMS.find(x=>x.id===id)?.label).join("、")}/>
              {preview.pudoNotes?.ancestor&&<InfoRow label="　祖先資料" value={preview.pudoNotes.ancestor}/>}
              {preview.pudoNotes?.baby&&<InfoRow label="　嬰靈資料" value={preview.pudoNotes.baby}/>}
            </>}
            {preview.cats?.includes("treasury")&&<InfoRow label="補財庫" value={`${preview.treasurySeason}　$1,500`}/>}
            {preview.cats?.includes("restore") &&<InfoRow label="還庫藏" value="$1,500"/>}
            {preview.cats?.includes("sponsor") &&<InfoRow label="善款金額" value={`NT$ ${(+preview.sponsorAmount||0).toLocaleString()}`}/>}
            {preview.note&&<InfoRow label="備註" value={preview.note}/>}
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:12,paddingTop:12,borderTop:`1px solid ${C.border}`}}>
              <span style={{color:C.sub,fontWeight:700}}>應繳金額</span>
              <span style={{fontSize:24,fontWeight:900,color:C.red}}>NT$ {preview.total?.toLocaleString()}</span>
            </div>
          </div>

          <div style={{background:"#fff",border:`1px solid ${C.border}`,borderRadius:14,padding:"18px",marginBottom:16,boxShadow:"0 1px 6px #0000000d"}}>
            <div style={{fontWeight:700,fontSize:14,color:C.text,marginBottom:14,paddingBottom:10,borderBottom:`1px solid ${C.border}`}}>💳 選擇付款方式</div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
              {[{id:"atTemple",icon:"🏮",title:"到宮裡繳費",desc:"親至本宮服務台繳交費用"},{id:"transfer",icon:"🏦",title:"匯款",desc:"轉帳後請回傳收據"}].map(m=>{
                const sel=payMethod===m.id;
                return (
                  <div key={m.id} onClick={()=>setPayMethod(m.id)} style={{padding:"16px 12px",cursor:"pointer",borderRadius:10,textAlign:"center",border:`2px solid ${sel?C.red:C.border}`,background:sel?C.redL:"#faf6f0",transition:"all .15s"}}>
                    <div style={{fontSize:28,marginBottom:6}}>{m.icon}</div>
                    <div style={{fontWeight:700,fontSize:14,color:sel?C.red:C.text,marginBottom:4}}>{m.title}</div>
                    <div style={{fontSize:11,color:C.muted,lineHeight:1.5}}>{m.desc}</div>
                    {sel&&<div style={{fontSize:11,color:C.gold,marginTop:6,fontWeight:700}}>✓ 已選擇</div>}
                  </div>
                );
              })}
            </div>
            {payMethod==="transfer"&&(
              <div style={{marginTop:14,padding:"12px 14px",background:C.goldL,borderRadius:8,border:`1px solid ${C.gold}50`}}>
                <div style={{fontWeight:700,fontSize:13,color:C.gold,marginBottom:8}}>🏦 匯款帳號資訊</div>
                <div style={{fontSize:13,color:C.text,lineHeight:2}}>
                  <div>銀行：○○銀行 八里分行</div>
                  <div>帳號：000-000-000000</div>
                  <div>戶名：無極受玄宮</div>
                </div>
                <div style={{fontSize:11,color:C.sub,marginTop:8}}>※ 匯款後請將收據照片傳至廟方聯絡人</div>
              </div>
            )}
          </div>

          <div style={{display:"grid",gridTemplateColumns:"1fr 2fr",gap:10}}>
            <button onClick={()=>{setPreview(null);setTab("register");}} style={{padding:"13px 0",background:"#fff",border:`1px solid ${C.border}`,borderRadius:10,color:C.sub,fontSize:14,fontWeight:700,cursor:"pointer",fontFamily:"inherit"}}>← 返回修改</button>
            <button onClick={()=>{ if(!payMethod){alert("請選擇付款方式");return;} confirmSubmit(payMethod); }}
              disabled={!payMethod||saving} style={{padding:"13px 0",background:payMethod?`linear-gradient(135deg,${C.red},#7a2a2a)`:"#e0d0c0",border:`2px solid ${payMethod?C.gold:C.border}`,borderRadius:10,color:payMethod?"#fff":C.muted,fontSize:15,fontWeight:700,letterSpacing:3,cursor:payMethod?"pointer":"not-allowed",fontFamily:"inherit",transition:"all .2s"}}>
              {saving?"儲存中...":"🏮 確認完成登記"}
            </button>
          </div>
        </div>
        )}

        {/* ═══ 進香報名 ═══ */}
        {tab==="pilgrim"&&(
        <div>
          {pilDone ? (
            <div style={{textAlign:"center",paddingTop:10}}>
              <div style={{fontSize:48,marginBottom:8}}>🚌</div>
              <div style={{fontSize:20,fontWeight:700,color:C.red,letterSpacing:2,marginBottom:5}}>報名成功！</div>
              <div style={{color:C.sub,marginBottom:16,fontSize:13}}>感謝您報名參加進香活動</div>
              <div style={{background:"#fff",border:`1px solid ${C.border}`,borderRadius:14,padding:"18px 16px",textAlign:"left",marginBottom:16}}>
                <div style={{color:C.red,fontWeight:700,fontSize:13,letterSpacing:3,textAlign:"center",marginBottom:12}}>八里無極受玄宮　進香報名憑單</div>
                <InfoRow label="報名編號" value={pilDone.serialNo} hi/>
                <InfoRow label="報名日期" value={pilDone.registeredAt}/>
                <InfoRow label="活動" value={pilSettings.title}/>
                {pilSettings.date&&<InfoRow label="進香日期" value={pilSettings.date}/>}
                <InfoRow label="姓名" value={pilDone.name}/>
                <InfoRow label="電話" value={pilDone.phone}/>
                <InfoRow label="身分證" value={pilDone.idNo}/>
                <InfoRow label="生日" value={pilDone.birthday}/>
                <InfoRow label="地址" value={pilDone.address}/>
                <InfoRow label="葷素" value={pilDone.vegetarian}/>
                {pilDone.note&&<InfoRow label="備註" value={pilDone.note}/>}
              </div>
              <button onClick={()=>setPilDone(null)} style={{padding:"12px 36px",background:`linear-gradient(135deg,${C.red},#7a2a2a)`,border:`2px solid ${C.gold}`,borderRadius:10,color:"#fff",fontSize:14,fontWeight:700,letterSpacing:2,cursor:"pointer",fontFamily:"inherit"}}>繼續報名</button>
            </div>
          ) : (
            <div>
              <div style={{background:C.goldL,border:`1px solid ${C.gold}50`,borderRadius:12,padding:"14px 16px",marginBottom:14,textAlign:"center"}}>
                <div style={{fontSize:22,marginBottom:4}}>🚌</div>
                <div style={{fontWeight:700,fontSize:16,color:C.red,letterSpacing:2}}>{pilSettings.title}</div>
                {pilSettings.date&&<div style={{fontSize:13,color:C.sub,marginTop:4}}>進香日期：{pilSettings.date}</div>}
              </div>
              <Section title="報名基本資料" icon="📋">
                <div style={{marginBottom:12}}>
                  <Lbl t="姓名 *"/>
                  <input value={pilForm.name} onChange={e=>{setPil("name",e.target.value);clrPilE("name");}} placeholder="請輸入姓名" style={inp}/>
                  <Err c={pilErr.name}/>
                </div>
                <div style={{marginBottom:12}}>
                  <Lbl t="電話 *"/>
                  <input value={pilForm.phone} onChange={e=>{setPil("phone",e.target.value);clrPilE("phone");}} placeholder="0912-345-678" style={inp}/>
                  <Err c={pilErr.phone}/>
                </div>
                <div style={{marginBottom:12}}>
                  <Lbl t="身分證字號 *"/>
                  <input value={pilForm.idNo} onChange={e=>{setPil("idNo",e.target.value);clrPilE("idNo");}} placeholder="A123456789" style={inp}/>
                  <Err c={pilErr.idNo}/>
                </div>
                <div style={{marginBottom:12}}>
                  <Lbl t="生日（國曆）*"/>
                  <input value={pilForm.birthday} onChange={e=>{setPil("birthday",e.target.value);clrPilE("birthday");}} placeholder="例：1980/01/01" style={inp}/>
                  <Err c={pilErr.birthday}/>
                </div>
                <div style={{marginBottom:12}}>
                  <Lbl t="地址 *"/>
                  <input value={pilForm.address} onChange={e=>{setPil("address",e.target.value);clrPilE("address");}} placeholder="請輸入地址" style={inp}/>
                  <Err c={pilErr.address}/>
                </div>
                <div style={{marginBottom:12}}>
                  <Lbl t="葷食／素食"/>
                  <div style={{display:"flex",gap:16}}>
                    {["葷食","素食"].map(v=>(
                      <label key={v} style={{display:"flex",alignItems:"center",gap:6,cursor:"pointer",fontSize:14}}>
                        <input type="radio" checked={pilForm.vegetarian===v} onChange={()=>setPil("vegetarian",v)} style={{accentColor:C.red}}/>{v}
                      </label>
                    ))}
                  </div>
                </div>
                <div style={{marginBottom:4}}>
                  <Lbl t="備註"/>
                  <textarea value={pilForm.note} onChange={e=>setPil("note",e.target.value)} placeholder="如有特殊需求請填寫" rows={3} style={{...inp,resize:"vertical",fontSize:13}}/>
                </div>
              </Section>
              <div style={{background:C.goldL,border:`1px solid ${C.gold}50`,borderRadius:10,padding:"10px 14px",marginBottom:14,fontSize:12,color:C.sub}}>
                ※ 金額由廟方人員填寫，報名後請洽廟方確認費用及付款方式。
              </div>
              <button onClick={submitPil} disabled={pilSaving} style={{width:"100%",padding:"14px 0",background:`linear-gradient(135deg,${C.red},#7a2a2a)`,border:`2px solid ${C.gold}`,borderRadius:10,color:"#fff",fontSize:15,fontWeight:700,letterSpacing:3,cursor:"pointer",fontFamily:"inherit"}}>
                {pilSaving?"儲存中...":"🚌 確認報名"}
              </button>
            </div>
          )}
        </div>
        )}

        {/* ═══ 完成 ═══ */}
        {tab==="done"&&done&&(
        <div style={{textAlign:"center",paddingTop:10}}>
          <div style={{fontSize:52,marginBottom:8}}>🏮</div>
          <div style={{fontSize:21,fontWeight:700,color:C.red,letterSpacing:3,marginBottom:5}}>登記成功！</div>
          <div style={{color:C.sub,marginBottom:12,fontSize:13}}>感謝您的虔誠，神明庇佑平安順遂</div>
          {done.payMethod==="transfer"&&(
            <div style={{background:C.goldL,border:`1px solid ${C.gold}50`,borderRadius:10,padding:"12px 16px",marginBottom:16,textAlign:"left"}}>
              <div style={{fontWeight:700,fontSize:13,color:C.gold,marginBottom:6}}>🏦 匯款帳號資訊</div>
              <div style={{fontSize:13,color:C.text,lineHeight:2}}>
                <div>銀行：○○銀行 八里分行</div>
                <div>帳號：000-000-000000</div>
                <div>戶名：無極受玄宮</div>
              </div>
              <div style={{fontSize:11,color:C.sub,marginTop:6}}>※ 匯款後請將收據照片傳至廟方聯絡人</div>
            </div>
          )}
          <div style={{background:"#fff",border:`1px solid ${C.border}`,borderRadius:14,padding:"20px 18px",textAlign:"left",marginBottom:16,boxShadow:"0 1px 6px #0000000d"}}>
            <div style={{color:C.red,fontWeight:700,fontSize:13,letterSpacing:4,textAlign:"center",marginBottom:14}}>八里無極受玄宮　登記憑單</div>
            <InfoRow label="登記編號" value={done.serialNo} hi/>
            <InfoRow label="登記日期" value={done.registeredAt}/>
            <InfoRow label="信眾姓名" value={`${done.name}（${done.gender}）`}/>
            <InfoRow label="出生年次" value={`民國${toROC(done.birthYear)}年（${zodiac(done.birthYear)}）`}/>
            <InfoRow label="農曆生日" value={`${done.lunarMonth}${done.lunarDay}`}/>
            <InfoRow label="聯絡電話" value={done.phone}/>
            <InfoRow label="地址"     value={done.address}/>
            {done.lights?.length>0&&<InfoRow label="點燈項目" value={done.lights.map(id=>LIGHT_ITEMS.find(x=>x.id===id)?.label).join("、")}/>}
            {done.pudos?.length>0&&<>
              <InfoRow label="普渡項目" value={done.pudos.map(id=>PUDO_ITEMS.find(x=>x.id===id)?.label).join("、")}/>
              {done.pudoNotes?.ancestor&&<InfoRow label="　祖先資料" value={done.pudoNotes.ancestor}/>}
              {done.pudoNotes?.baby&&<InfoRow label="　嬰靈資料" value={done.pudoNotes.baby}/>}
            </>}
            {done.cats?.includes("treasury")&&<InfoRow label="補財庫" value={`${done.treasurySeason}　$1,500`}/>}
            {done.cats?.includes("restore") &&<InfoRow label="還庫藏" value="$1,500"/>}
            {done.cats?.includes("sponsor") &&<InfoRow label="善款金額" value={`NT$ ${(+done.sponsorAmount||0).toLocaleString()}`}/>}
            {done.payMethod&&<InfoRow label="付款方式" value={done.payMethod==="atTemple"?"🏮 到宮裡繳費":"🏦 匯款"}/>}
            {done.note&&<InfoRow label="備註" value={done.note}/>}
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:12,paddingTop:12,borderTop:`1px solid ${C.border}`}}>
              <span style={{color:C.sub}}>應繳金額</span>
              <span style={{fontSize:22,fontWeight:900,color:C.red}}>NT$ {done.total?.toLocaleString()}</span>
            </div>
          </div>
          <div style={{background:"#06C755",borderRadius:14,padding:"16px 20px",marginBottom:16,textAlign:"center"}}>
            <div style={{fontSize:13,color:"#fff",marginBottom:10,opacity:.9}}>加入官方 LINE 掌握最新活動消息</div>
            <a href={LINE_URL} target="_blank" rel="noreferrer" style={{display:"inline-flex",alignItems:"center",gap:8,background:"#fff",borderRadius:10,padding:"10px 24px",color:"#06C755",fontWeight:700,fontSize:15,textDecoration:"none"}}>
              {LINE_SVG_LG} 加入 LINE 官方帳號
            </a>
          </div>
          <button onClick={()=>{setDone(null);setTab("register");}} style={{padding:"12px 36px",background:`linear-gradient(135deg,${C.red},#7a2a2a)`,border:`2px solid ${C.gold}`,borderRadius:10,color:"#fff",fontSize:14,fontWeight:700,letterSpacing:3,cursor:"pointer",fontFamily:"inherit"}}>繼續登記</button>
        </div>
        )}

        {/* ═══ 查詢 ═══ */}
        {tab==="records"&&(
        <div>
          {!qAuth&&!isAdmin&&(
            <div style={{background:"#fff",border:`1px solid ${C.border}`,borderRadius:14,padding:"24px 20px",boxShadow:"0 1px 6px #0000000d"}}>
              <div style={{textAlign:"center",marginBottom:20}}>
                <div style={{fontSize:32,marginBottom:8}}>🔍</div>
                <div style={{fontWeight:700,fontSize:16,color:C.text,marginBottom:4}}>查詢登記資料</div>
                <div style={{fontSize:13,color:C.sub}}>請輸入登記時填寫的姓名及電話</div>
              </div>
              <div style={{marginBottom:12}}><Lbl t="姓名"/><input value={qInput.name} onChange={e=>{setQInput(q=>({...q,name:e.target.value}));setQErr("");}} placeholder="請輸入登記姓名" style={inp}/></div>
              <div style={{marginBottom:16}}><Lbl t="聯絡電話"/><input value={qInput.phone} onChange={e=>{setQInput(q=>({...q,phone:e.target.value}));setQErr("");}} placeholder="請輸入登記電話" style={inp} onKeyDown={e=>e.key==="Enter"&&doQueryAuth()}/></div>
              {qErr&&<div style={{fontSize:12,color:C.red,marginBottom:12,textAlign:"center"}}>{qErr}</div>}
              <button onClick={doQueryAuth} style={{width:"100%",padding:"12px 0",background:`linear-gradient(135deg,${C.red},#7a2a2a)`,border:`2px solid ${C.gold}`,borderRadius:10,color:"#fff",fontSize:15,fontWeight:700,letterSpacing:3,cursor:"pointer",fontFamily:"inherit"}}>確認查詢</button>
            </div>
          )}
          {qAuth&&!isAdmin&&(()=>{
            const myRecs=records.filter(r=>r.name===qInput.name.trim()&&r.phone===qInput.phone.trim());
            return (
              <div>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
                  <div style={{fontSize:13,color:C.sub}}>共找到 <b style={{color:C.red}}>{myRecs.length}</b> 筆登記</div>
                  <button onClick={()=>{setQAuth(false);setQInput({name:"",phone:""});}} style={{padding:"5px 14px",background:"#fff",border:`1px solid ${C.border}`,borderRadius:6,fontSize:12,color:C.sub,cursor:"pointer",fontFamily:"inherit"}}>重新查詢</button>
                </div>
                {myRecs.length===0&&<div style={{textAlign:"center",color:C.muted,padding:40}}>查無您的登記紀錄</div>}
                {myRecs.map(r=><RecordCard key={r.id} r={r}/>)}
              </div>
            );
          })()}
          {isAdmin&&(
            <div>
              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:14,padding:"10px 14px",background:C.goldL,borderRadius:8,border:`1px solid ${C.gold}50`}}>
                <span>🔑</span>
                <span style={{fontSize:13,color:C.gold,fontWeight:700}}>管理者模式・{user?.email}</span>
              </div>
              <input value={srch} onChange={e=>setSrch(e.target.value)} placeholder="🔍 搜尋姓名 / 電話 / 編號" style={{...inp,marginBottom:14}}/>
              {loading?<div style={{textAlign:"center",color:C.muted,padding:40}}>載入中...</div>:records.filter(r=>r.name?.includes(srch)||r.phone?.includes(srch)||r.serialNo?.includes(srch)).map(r=><RecordCard key={r.id} r={r}/>)}
              {!loading&&records.length===0&&<div style={{textAlign:"center",color:C.muted,padding:50}}>尚無登記紀錄</div>}
            </div>
          )}
        </div>
        )}

        {/* ═══ 管理 ═══ */}
        {tab==="admin"&&(
        <div>
          {!isAdmin?(
            <div style={{textAlign:"center",padding:"40px 20px"}}>
              <div style={{fontSize:36,marginBottom:12}}>🔐</div>
              <div style={{fontWeight:700,fontSize:16,color:C.text,marginBottom:8}}>管理者登入</div>
              <div style={{fontSize:13,color:C.sub,marginBottom:20}}>請使用授權的 Google 帳號登入</div>
              <button onClick={loginAdmin} style={{padding:"12px 32px",background:`linear-gradient(135deg,${C.red},#7a2a2a)`,border:`2px solid ${C.gold}`,borderRadius:10,color:"#fff",fontSize:15,fontWeight:700,cursor:"pointer",fontFamily:"inherit"}}>
                🔑 Google 登入
              </button>
            </div>
          ):(
          <div>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14,padding:"10px 14px",background:C.goldL,borderRadius:8,border:`1px solid ${C.gold}50`}}>
              <span style={{fontSize:13,color:C.gold,fontWeight:700}}>🔑 {user?.email}</span>
              <button onClick={()=>signOut(auth)} style={{padding:"4px 12px",background:"#fff",border:`1px solid ${C.border}`,borderRadius:6,fontSize:12,color:C.sub,cursor:"pointer",fontFamily:"inherit"}}>登出</button>
            </div>

            {/* 付款狀態統計 */}
            <div style={{display:"flex",gap:8,marginBottom:12,flexWrap:"wrap"}}>
              {[{id:"all",label:"全部",icon:"📋"},...PAY_STATUS].map(s=>{
                const cnt=s.id==="all"?adminFiltered.length:adminFiltered.filter(r=>(r.payStatus||"pending")===s.id).length;
                return <div key={s.id} style={{padding:"6px 14px",borderRadius:20,fontSize:12,fontWeight:600,background:s.id==="all"?C.goldL:(s.bg||C.goldL),color:s.id==="all"?C.gold:(s.color||C.gold),border:`1px solid ${s.id==="all"?C.gold+"50":(s.color||C.gold)+"40"}`}}>{s.icon} {s.label}：{cnt} 筆</div>;
              })}
            </div>

            {/* 統計卡 */}
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:10,marginBottom:16}}>
              {[
                {label:"篩選筆數",value:`${adminFiltered.length} 筆`,icon:"📋"},
                {label:"今日登記",value:`${records.filter(r=>r.registeredAt?.startsWith(new Date().toLocaleDateString("zh-TW"))).length} 筆`,icon:"📅"},
                {label:"篩選收入",value:`$${adminFiltered.reduce((s,r)=>s+(r.total||0),0).toLocaleString()}`,icon:"💰"},
              ].map(s=>(
                <div key={s.label} style={{background:"#fff",border:`1px solid ${C.border}`,borderRadius:12,padding:"14px 12px",textAlign:"center",boxShadow:"0 1px 4px #0000000a"}}>
                  <div style={{fontSize:20,marginBottom:4}}>{s.icon}</div>
                  <div style={{fontSize:16,fontWeight:700,color:C.red,marginBottom:2}}>{s.value}</div>
                  <div style={{fontSize:11,color:C.muted}}>{s.label}</div>
                </div>
              ))}
            </div>

            {/* 搜尋 + 日期區間 */}
            <div style={{background:"#fff",border:`1px solid ${C.border}`,borderRadius:12,padding:"14px 16px",marginBottom:14,boxShadow:"0 1px 4px #0000000a"}}>
              <input value={adminSrch} onChange={e=>setAdminSrch(e.target.value)} placeholder="🔍 搜尋姓名 / 電話 / 編號" style={{...inp,marginBottom:10}}/>
              <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
                <div style={{fontSize:12,color:C.sub,whiteSpace:"nowrap"}}>登記日期</div>
                <input type="date" value={dateFrom} onChange={e=>setDateFrom(e.target.value)} style={{...inp,flex:1,minWidth:130,padding:"7px 10px",fontSize:13}}/>
                <div style={{fontSize:12,color:C.muted}}>～</div>
                <input type="date" value={dateTo} onChange={e=>setDateTo(e.target.value)} style={{...inp,flex:1,minWidth:130,padding:"7px 10px",fontSize:13}}/>
                {(dateFrom||dateTo)&&<button onClick={()=>{setDateFrom("");setDateTo("");}} style={{padding:"7px 12px",background:C.redL,border:`1px solid ${C.red}50`,borderRadius:6,color:C.red,fontSize:12,cursor:"pointer",fontFamily:"inherit",whiteSpace:"nowrap"}}>清除</button>}
              </div>
              {(dateFrom||dateTo)&&<div style={{fontSize:11,color:C.gold,marginTop:8}}>篩選中：{dateFrom||"最早"} ～ {dateTo||"最新"}，共 {adminFiltered.length} 筆</div>}
            </div>

            {/* 分項下載 */}
            <div style={{background:"#fff",border:`1px solid ${C.border}`,borderRadius:12,padding:"14px 16px",marginBottom:14,boxShadow:"0 1px 4px #0000000a"}}>
              <div style={{fontWeight:700,fontSize:13,color:C.text,marginBottom:12,paddingBottom:8,borderBottom:`1px solid ${C.border}`}}>⬇ 下載 Excel</div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
                {[
                  {label:"全部資料",icon:"📋",filter:r=>true},
                  {label:"點燈",    icon:"🏮",filter:r=>r.cats?.includes("light")},
                  {label:"普渡",    icon:"🪔",filter:r=>r.cats?.includes("pudo")},
                  {label:"補財庫",  icon:"💰",filter:r=>r.cats?.includes("treasury")},
                  {label:"還庫藏",  icon:"✨",filter:r=>r.cats?.includes("restore")},
                  {label:"善款",    icon:"🙏",filter:r=>r.cats?.includes("sponsor")},
                ].map(opt=>{
                  const filtered=adminFiltered.filter(opt.filter);
                  return (
                    <button key={opt.label} onClick={()=>exportCSV(filtered,opt.label)} disabled={filtered.length===0} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"10px 12px",background:filtered.length>0?"#edf5ed":"#f5f5f5",border:`1px solid ${filtered.length>0?"#5a8a5a50":C.border}`,borderRadius:8,cursor:filtered.length>0?"pointer":"not-allowed",fontFamily:"inherit",transition:"all .15s"}}>
                      <span style={{fontSize:13,color:filtered.length>0?C.success:C.muted,fontWeight:600}}>{opt.icon} {opt.label}</span>
                      <span style={{fontSize:12,color:filtered.length>0?C.success:C.muted,background:filtered.length>0?"#c8e6c8":"#eee",padding:"2px 8px",borderRadius:12,fontWeight:700}}>{filtered.length} 筆</span>
                    </button>
                  );
                })}
              </div>
            </div>

            {/* 進香報名設定 */}
            <div style={{background:"#fff",border:`1px solid ${C.border}`,borderRadius:12,padding:"14px 16px",marginBottom:14,boxShadow:"0 1px 4px #0000000a"}}>
              <div style={{fontWeight:700,fontSize:13,color:C.text,marginBottom:12,paddingBottom:8,borderBottom:`1px solid ${C.border}`}}>🚌 進香報名設定</div>
              <div style={{marginBottom:10,display:"flex",alignItems:"center",gap:10}}>
                <span style={{fontSize:13,color:C.sub}}>開放報名</span>
                <div onClick={()=>savePilSettings({...pilSettings,enabled:!pilSettings.enabled})} style={{width:44,height:24,borderRadius:12,background:pilSettings.enabled?"#9b3a3a":"#ccc",cursor:"pointer",position:"relative",transition:"background .2s"}}>
                  <div style={{position:"absolute",top:2,left:pilSettings.enabled?22:2,width:20,height:20,borderRadius:"50%",background:"#fff",transition:"left .2s"}}/>
                </div>
                <span style={{fontSize:12,color:pilSettings.enabled?C.red:C.muted,fontWeight:700}}>{pilSettings.enabled?"開放中":"已關閉"}</span>
              </div>
              <div style={{marginBottom:10}}>
                <Lbl t="活動標題"/>
                <input value={pilSettings.title} onChange={e=>setPilSettings(s=>({...s,title:e.target.value}))} style={inp}/>
              </div>
              <div style={{marginBottom:10}}>
                <Lbl t="進香日期"/>
                <input value={pilSettings.date} onChange={e=>setPilSettings(s=>({...s,date:e.target.value}))} placeholder="例：114年3月15日" style={inp}/>
              </div>
              <button onClick={()=>savePilSettings(pilSettings)} style={{padding:"8px 18px",background:C.red,border:"none",borderRadius:8,color:"#fff",fontSize:13,fontWeight:700,cursor:"pointer",fontFamily:"inherit"}}>儲存設定</button>
            </div>

            {/* 進香報名清單 */}
            {pilDelConf&&(
              <div style={{position:"fixed",inset:0,background:"#0006",zIndex:999,display:"flex",alignItems:"center",justifyContent:"center"}}>
                <div style={{background:"#fff",borderRadius:16,padding:"24px",width:280,boxShadow:"0 8px 32px #0003",textAlign:"center"}}>
                  <div style={{fontSize:22,marginBottom:10}}>⚠️</div>
                  <div style={{fontWeight:700,color:C.text,marginBottom:6}}>確認刪除進香報名？</div>
                  <div style={{fontSize:13,color:C.sub,marginBottom:18}}>{pilDelConf.name}・{pilDelConf.serialNo}</div>
                  <div style={{display:"flex",gap:10}}>
                    <button onClick={()=>setPilDelConf(null)} style={{flex:1,padding:"9px 0",background:C.bg,border:`1px solid ${C.border}`,borderRadius:8,cursor:"pointer",fontFamily:"inherit",fontSize:13,color:C.sub}}>取消</button>
                    <button onClick={()=>deletePilRecord(pilDelConf.id)} style={{flex:1,padding:"9px 0",background:C.red,border:"none",borderRadius:8,cursor:"pointer",fontFamily:"inherit",fontSize:13,color:"#fff",fontWeight:700}}>刪除</button>
                  </div>
                </div>
              </div>
            )}
            <div style={{background:"#fff",border:`1px solid ${C.border}`,borderRadius:12,padding:"14px 16px",marginBottom:14,boxShadow:"0 1px 4px #0000000a"}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12,paddingBottom:8,borderBottom:`1px solid ${C.border}`}}>
                <span style={{fontWeight:700,fontSize:13,color:C.text}}>🚌 進香報名名單（{pilRecords.length}筆）</span>
                <button onClick={()=>exportPilCSV(pilRecords)} disabled={pilRecords.length===0} style={{padding:"5px 12px",background:"#edf5ed",border:"1px solid #5a8a5a50",borderRadius:6,color:"#5a8a5a",fontSize:12,cursor:pilRecords.length>0?"pointer":"not-allowed",fontFamily:"inherit",fontWeight:600}}>⬇ 下載CSV</button>
              </div>
              <input value={pilAdminSrch} onChange={e=>setPilAdminSrch(e.target.value)} placeholder="🔍 搜尋姓名 / 電話 / 編號" style={{...inp,marginBottom:10}}/>
              {pilRecords.filter(r=>!pilAdminSrch||r.name?.includes(pilAdminSrch)||r.phone?.includes(pilAdminSrch)||r.serialNo?.includes(pilAdminSrch)).map(r=>(
                <div key={r.id} style={{background:C.bg,border:`1px solid ${C.border}`,borderRadius:10,padding:"12px 14px",marginBottom:8}}>
                  <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:6}}>
                    <div>
                      <span style={{fontWeight:700,fontSize:14,color:C.text}}>{r.name}</span>
                      <span style={{fontSize:12,color:C.muted,marginLeft:8}}>{r.phone}・{r.vegetarian}</span>
                    </div>
                    <div style={{display:"flex",gap:5,flexWrap:"wrap",justifyContent:"flex-end"}}>
                      <span style={{fontSize:11,color:C.gold,background:C.goldL,padding:"2px 8px",borderRadius:20,border:`1px solid ${C.gold}50`}}>{r.serialNo}</span>
                      {PAY_STATUS.map(s=>{
                        const active=(r.payStatus||"pending")===s.id;
                        return <button key={s.id} onClick={()=>updatePilStatus(r.id,s.id)} style={{padding:"3px 8px",borderRadius:6,fontSize:10,cursor:"pointer",fontFamily:"inherit",border:`1px solid ${active?s.color:C.border}`,background:active?s.bg:"#fff",color:active?s.color:C.muted,fontWeight:active?700:400}}>{s.icon}{s.label}</button>;
                      })}
                      <button onClick={()=>setPilDelConf(r)} style={{padding:"3px 8px",background:"#fff",border:`1px solid ${C.red}60`,borderRadius:6,color:C.red,fontSize:10,cursor:"pointer",fontFamily:"inherit"}}>刪除</button>
                    </div>
                  </div>
                  <div style={{fontSize:12,color:C.sub,marginBottom:6}}>
                    身分證：{r.idNo}・生日：{r.birthday}<br/>地址：{r.address}
                    {r.note&&<><br/>備註：{r.note}</>}
                  </div>
                  <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
                    <span style={{fontSize:11,color:C.muted}}>{r.registeredAt}</span>
                    <div style={{display:"flex",alignItems:"center",gap:6,marginLeft:"auto"}}>
                      <span style={{fontSize:12,color:C.sub}}>金額 NT$</span>
                      <input type="number" value={r.amount||""} onChange={e=>updatePilAmount(r.id,e.target.value)} placeholder="待填" style={{...inp,width:90,padding:"4px 8px",fontSize:13}}/>
                    </div>
                  </div>
                </div>
              ))}
              {pilRecords.length===0&&<div style={{textAlign:"center",color:C.muted,padding:20,fontSize:13}}>尚無進香報名</div>}
            </div>

            {/* 登記清單 */}
            {loading?<div style={{textAlign:"center",color:C.muted,padding:40}}>載入中...</div>:null}
            {adminFiltered.length===0&&!loading&&<div style={{textAlign:"center",color:C.muted,padding:40}}>查無資料</div>}
            {adminFiltered.map(r=>(
              <div key={r.id} style={{background:"#fff",border:`1px solid ${C.border}`,borderRadius:12,padding:"14px 16px",marginBottom:10,boxShadow:"0 1px 4px #0000000a"}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:7}}>
                  <div>
                    <span style={{fontWeight:700,fontSize:14,color:C.text}}>{r.name}</span>
                    <span style={{fontSize:12,color:C.muted,marginLeft:8}}>{r.gender}・{r.phone}</span>
                  </div>
                  <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap",justifyContent:"flex-end"}}>
                    <span style={{fontSize:11,color:C.gold,background:C.goldL,padding:"2px 8px",borderRadius:20,border:`1px solid ${C.gold}50`}}>{r.serialNo}</span>
                    {PAY_STATUS.map(s=>{
                      const active=(r.payStatus||"pending")===s.id;
                      return <button key={s.id} onClick={()=>updatePayStatus(r.id,s.id)} style={{padding:"3px 10px",borderRadius:6,fontSize:11,cursor:"pointer",fontFamily:"inherit",border:`1px solid ${active?s.color:C.border}`,background:active?s.bg:"#fff",color:active?s.color:C.muted,fontWeight:active?700:400}}>{s.icon} {s.label}</button>;
                    })}
                    <button onClick={()=>setDelConf(r)} style={{padding:"3px 10px",background:"#fff",border:`1px solid ${C.red}60`,borderRadius:6,color:C.red,fontSize:12,cursor:"pointer",fontFamily:"inherit"}}>刪除</button>
                  </div>
                </div>
                <div style={{fontSize:12,color:C.sub,lineHeight:1.8,marginBottom:6}}>
                  民國{toROC(r.birthYear)}年（{zodiac(r.birthYear)}）・農曆{r.lunarMonth}{r.lunarDay}
                  {r.lights?.length>0&&<> · 🏮 {r.lights.map(id=>LIGHT_ITEMS.find(x=>x.id===id)?.label).join("、")}</>}
                  {r.pudos?.length>0 &&<> · 🪔 {r.pudos.map(id=>PUDO_ITEMS.find(x=>x.id===id)?.label).join("、")}</>}
                  {r.cats?.includes("treasury")&&<> · 💰 補財庫{r.treasurySeason?`(${r.treasurySeason})`:""}</>}
                  {r.cats?.includes("restore") &&<> · ✨ 還庫藏</>}
                  {r.cats?.includes("sponsor") &&<> · 🙏 善款 NT${(+r.sponsorAmount||0).toLocaleString()}</>}
                  {r.address&&<> · {r.address}</>}
                </div>
                {(r.pudoNotes?.ancestor||r.pudoNotes?.baby)&&(
                  <div style={{fontSize:12,color:C.sub,background:C.goldL,borderRadius:6,padding:"6px 10px",marginBottom:6}}>
                    {r.pudoNotes.ancestor&&<div>祖先：{r.pudoNotes.ancestor}</div>}
                    {r.pudoNotes.baby&&<div>嬰靈：{r.pudoNotes.baby}</div>}
                  </div>
                )}
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                  <span style={{fontSize:11,color:C.muted}}>{r.registeredAt}　{r.payMethod==="atTemple"?"🏮到宮繳費":r.payMethod==="transfer"?"🏦匯款":""}</span>
                  <span style={{fontWeight:700,color:C.red}}>NT$ {r.total?.toLocaleString()}</span>
                </div>
              </div>
            ))}
          </div>
          )}
        </div>
        )}

      </div>

      {/* 浮動神明貼圖 */}
      <div style={{position:"fixed",bottom:20,right:16,zIndex:900,width:80,height:80,filter:"drop-shadow(0 4px 12px rgba(0,0,0,0.25))",animation:"bobbing 3s ease-in-out infinite"}}>
        <img src={STICKER_IMG} alt="神明貼圖" style={{width:"100%",height:"100%",objectFit:"contain",objectPosition:"top"}}/>
      </div>
      <style>{`@keyframes bobbing{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}`}</style>

    </div>
  );
}
